31	/**
32	 * This class is for maintaining the various Router Federation Interceptor
33	 * activity statistics and publishing them through the metrics interfaces.
34	 */
35	@InterfaceAudience.Private
36	@Metrics(about = "Metrics for Router Federation Interceptor", context = "fedr")
37	public final class RouterMetrics {
38	
39	  private static final MetricsInfo RECORD_INFO =
40	      info("RouterMetrics", "Router Federation Interceptor");
41	  private static AtomicBoolean isInitialized = new AtomicBoolean(false);
42	
43	  // Metrics for operation failed
44	  @Metric("# of applications failed to be submitted")
45	  private MutableGaugeInt numAppsFailedSubmitted;
46	  @Metric("# of applications failed to be created")
47	  private MutableGaugeInt numAppsFailedCreated;
48	  @Metric("# of applications failed to be killed")
49	  private MutableGaugeInt numAppsFailedKilled;
50	  @Metric("# of application reports failed to be retrieved")
51	  private MutableGaugeInt numAppsFailedRetrieved;
52	  @Metric("# of multiple applications reports failed to be retrieved")
53	  private MutableGaugeInt numMultipleAppsFailedRetrieved;
54	  @Metric("# of applicationAttempt reports failed to be retrieved")
55	  private MutableGaugeInt numAppAttemptsFailedRetrieved;
56	  @Metric("# of getClusterMetrics failed to be retrieved")
57	  private MutableGaugeInt numGetClusterMetricsFailedRetrieved;
58	
59	  // Aggregate metrics are shared, and don't have to be looked up per call
60	  @Metric("Total number of successful Submitted apps and latency(ms)")
61	  private MutableRate totalSucceededAppsSubmitted;
62	  @Metric("Total number of successful Killed apps and latency(ms)")
63	  private MutableRate totalSucceededAppsKilled;
64	  @Metric("Total number of successful Created apps and latency(ms)")
