66	  @Metric("Total number of successful Retrieved app reports and latency(ms)")
67	  private MutableRate totalSucceededAppsRetrieved;
68	  @Metric("Total number of successful Retrieved multiple apps reports and "
69	      + "latency(ms)")
70	  private MutableRate totalSucceededMultipleAppsRetrieved;
71	  @Metric("Total number of successful Retrieved " +
72	          "appAttempt reports and latency(ms)")
73	  private MutableRate totalSucceededAppAttemptsRetrieved;
74	  @Metric("Total number of successful Retrieved getClusterMetrics and "
75	      + "latency(ms)")
76	  private MutableRate totalSucceededGetClusterMetricsRetrieved;
77	
78	
79	  /**
80	   * Provide quantile counters for all latencies.
81	   */
82	  private MutableQuantiles submitApplicationLatency;
83	  private MutableQuantiles getNewApplicationLatency;
84	  private MutableQuantiles killApplicationLatency;
85	  private MutableQuantiles getApplicationReportLatency;
86	  private MutableQuantiles getApplicationsReportLatency;
87	  private MutableQuantiles getApplicationAttemptReportLatency;
88	  private MutableQuantiles getClusterMetricsLatency;
89	
90	  private static volatile RouterMetrics INSTANCE = null;
91	  private static MetricsRegistry registry;
92	
93	  private RouterMetrics() {
94	    registry = new MetricsRegistry(RECORD_INFO);
95	    registry.tag(RECORD_INFO, "Router");
96	    getNewApplicationLatency = registry.newQuantiles("getNewApplicationLatency",
97	        "latency of get new application", "ops", "latency", 10);
98	    submitApplicationLatency = registry.newQuantiles("submitApplicationLatency",
99	        "latency of submit application", "ops", "latency", 10);
100	    killApplicationLatency = registry.newQuantiles("killApplicationLatency",
101	        "latency of kill application", "ops", "latency", 10);
102	    getApplicationReportLatency =
103	        registry.newQuantiles("getApplicationReportLatency",
104	            "latency of get application report", "ops", "latency", 10);
105	    getApplicationsReportLatency =
106	        registry.newQuantiles("getApplicationsReportLatency",
107	            "latency of get applications report", "ops", "latency", 10);
108	    getApplicationAttemptReportLatency =
109	        registry.newQuantiles("getApplicationAttemptReportLatency",
110	                    "latency of get applicationattempt " +
111	                            "report", "ops", "latency", 10);
112	    getClusterMetricsLatency =
113	        registry.newQuantiles("getClusterMetricsLatency",
114	            "latency of get cluster metrics", "ops", "latency", 10);
115	  }
116	
117	  public static RouterMetrics getMetrics() {
118	    if (!isInitialized.get()) {
119	      synchronized (RouterMetrics.class) {
120	        if (INSTANCE == null) {
121	          INSTANCE = DefaultMetricsSystem.instance().register("RouterMetrics",
122	              "Metrics for the Yarn Router", new RouterMetrics());
123	          isInitialized.set(true);
124	        }
125	      }
126	    }
127	    return INSTANCE;
128	  }
129	
130	  @VisibleForTesting
131	  synchronized static void destroy() {
132	    isInitialized.set(false);
133	    INSTANCE = null;
134	  }
