33	/**
34	 * Util class for Router Yarn client API calls.
35	 */
36	public final class RouterYarnClientUtils {
37	
38	  private final static String PARTIAL_REPORT = "Partial Report ";
39	
40	  private RouterYarnClientUtils() {
41	
42	  }
43	
44	  public static GetClusterMetricsResponse merge(
45	      Collection<GetClusterMetricsResponse> responses) {
46	    YarnClusterMetrics tmp = YarnClusterMetrics.newInstance(0);
47	    for (GetClusterMetricsResponse response : responses) {
48	      YarnClusterMetrics metrics = response.getClusterMetrics();
49	      tmp.setNumNodeManagers(
50	          tmp.getNumNodeManagers() + metrics.getNumNodeManagers());
51	      tmp.setNumActiveNodeManagers(
52	          tmp.getNumActiveNodeManagers() + metrics.getNumActiveNodeManagers());
53	      tmp.setNumDecommissionedNodeManagers(
54	          tmp.getNumDecommissionedNodeManagers() + metrics
55	              .getNumDecommissionedNodeManagers());
56	      tmp.setNumLostNodeManagers(
57	          tmp.getNumLostNodeManagers() + metrics.getNumLostNodeManagers());
58	      tmp.setNumRebootedNodeManagers(tmp.getNumRebootedNodeManagers() + metrics
59	          .getNumRebootedNodeManagers());
60	      tmp.setNumUnhealthyNodeManagers(
61	          tmp.getNumUnhealthyNodeManagers() + metrics
62	              .getNumUnhealthyNodeManagers());
63	    }
64	    return GetClusterMetricsResponse.newInstance(tmp);
65	  }
66	
67	  /**
68	   * Merges a list of ApplicationReports grouping by ApplicationId.
69	   * Our current policy is to merge the application reports from the reachable
70	   * SubClusters.
71	   * @param responses a list of ApplicationResponse to merge
72	   * @param returnPartialResult if the merge ApplicationReports should contain
73	   * partial result or not
74	   * @return the merged ApplicationsResponse
75	   */
76	  public static GetApplicationsResponse mergeApplications(
77	      Collection<GetApplicationsResponse> responses,
78	      boolean returnPartialResult){
79	    Map<ApplicationId, ApplicationReport> federationAM = new HashMap<>();
80	    Map<ApplicationId, ApplicationReport> federationUAMSum = new HashMap<>();
81	
82	    for (GetApplicationsResponse appResponse : responses){
83	      for (ApplicationReport appReport : appResponse.getApplicationList()){
84	        ApplicationId appId = appReport.getApplicationId();
85	        // Check if this ApplicationReport is an AM
86	        if (!appReport.isUnmanagedApp()) {
87	          // Insert in the list of AM
88	          federationAM.put(appId, appReport);
89	          // Check if there are any UAM found before
90	          if (federationUAMSum.containsKey(appId)) {
91	            // Merge the current AM with the found UAM
92	            mergeAMWithUAM(appReport, federationUAMSum.get(appId));
93	            // Remove the sum of the UAMs
94	            federationUAMSum.remove(appId);
95	          }
96	          // This ApplicationReport is an UAM
97	        } else if (federationAM.containsKey(appId)) {
98	          // Merge the current UAM with its own AM
99	          mergeAMWithUAM(federationAM.get(appId), appReport);
100	        } else if (federationUAMSum.containsKey(appId)) {
101	          // Merge the current UAM with its own UAM and update the list of UAM
102	          ApplicationReport mergedUAMReport =
103	              mergeUAMWithUAM(federationUAMSum.get(appId), appReport);
104	          federationUAMSum.put(appId, mergedUAMReport);
105	        } else {
106	          // Insert in the list of UAM
107	          federationUAMSum.put(appId, appReport);
108	        }
109	      }
110	    }
111	    // Check the remaining UAMs are depending or not from federation
112	    for (ApplicationReport appReport : federationUAMSum.values()) {
113	      if (mergeUamToReport(appReport.getName(), returnPartialResult)) {
114	        federationAM.put(appReport.getApplicationId(), appReport);
115	      }
116	    }
117	
118	    return GetApplicationsResponse.newInstance(federationAM.values());
119	  }
120	
121	  private static ApplicationReport mergeUAMWithUAM(ApplicationReport uam1,
122	      ApplicationReport uam2){
123	    uam1.setName(PARTIAL_REPORT + uam1.getApplicationId());
124	    mergeAMWithUAM(uam1, uam2);
125	    return uam1;
126	  }
127	
128	  private static void mergeAMWithUAM(ApplicationReport am,
129	      ApplicationReport uam){
130	    ApplicationResourceUsageReport amResourceReport =
131	        am.getApplicationResourceUsageReport();
132	
133	    ApplicationResourceUsageReport uamResourceReport =
134	        uam.getApplicationResourceUsageReport();
135	
136	    if (amResourceReport == null) {
137	      am.setApplicationResourceUsageReport(uamResourceReport);
138	    } else if (uamResourceReport != null) {
139	
140	      amResourceReport.setNumUsedContainers(
141	          amResourceReport.getNumUsedContainers() +
142	              uamResourceReport.getNumUsedContainers());
143	
144	      amResourceReport.setNumReservedContainers(
145	          amResourceReport.getNumReservedContainers() +
146	              uamResourceReport.getNumReservedContainers());
147	
148	      amResourceReport.setUsedResources(Resources.add(
149	          amResourceReport.getUsedResources(),
150	          uamResourceReport.getUsedResources()));
151	
152	      amResourceReport.setReservedResources(Resources.add(
153	          amResourceReport.getReservedResources(),
154	          uamResourceReport.getReservedResources()));
155	
156	      amResourceReport.setNeededResources(Resources.add(
157	          amResourceReport.getNeededResources(),
158	          uamResourceReport.getNeededResources()));
159	
160	      amResourceReport.setMemorySeconds(
161	          amResourceReport.getMemorySeconds() +
162	              uamResourceReport.getMemorySeconds());
163	
164	      amResourceReport.setVcoreSeconds(
165	          amResourceReport.getVcoreSeconds() +
166	              uamResourceReport.getVcoreSeconds());
167	
168	      amResourceReport.setQueueUsagePercentage(
169	          amResourceReport.getQueueUsagePercentage() +
170	              uamResourceReport.getQueueUsagePercentage());
171	
172	      amResourceReport.setClusterUsagePercentage(
173	          amResourceReport.getClusterUsagePercentage() +
174	              uamResourceReport.getClusterUsagePercentage());
175	
176	      am.setApplicationResourceUsageReport(amResourceReport);
177	    }
178	  }
179	
180	  /**
181	   * Returns whether or not to add an unmanaged application to the report.
182	   * @param appName Application Name
183	   * @param returnPartialResult if the merge ApplicationReports should contain
184	   * partial result or not
185	   */
186	  private static boolean mergeUamToReport(String appName,
187	      boolean returnPartialResult){
188	    if (returnPartialResult) {
189	      return true;
190	    }
191	    if (appName == null) {
192	      return false;
193	    }
194	    return !(appName.startsWith(UnmanagedApplicationManager.APP_NAME) ||
195	        appName.startsWith(PARTIAL_REPORT));
196	  }
197	}
